package app.repositories

import app.common.Page
import app.entities.Note

/** Keeps notes rows in memory, for tests and for trying the services without a database. */
class MemoryNoteRepository : NoteRepository {
    private val rows = linkedMapOf<List<Any?>, Note>()

    /** The key of a row, as a list of its key values. */
    private fun keyOf(row: Note): List<Any?> = listOf(row.id)

    /** Orders two keys value by value. */
    @Suppress("UNCHECKED_CAST")
    private fun compareKeys(a: List<Any?>, b: List<Any?>): Int {
        for (index in a.indices) {
            val order = compareValues(a[index] as Comparable<Any>?, b[index] as Comparable<Any>?)
            if (order != 0) return order
        }
        return 0
    }

    private fun visible(): List<Note> =
        rows.values.filter { true }.sortedWith { a, b -> compareKeys(keyOf(a), keyOf(b)) }

    override fun findById(id: Int): Note? {
        return visible().firstOrNull { it.id == id }
    }

    override fun list(offset: Int, limit: Int): Page<Note> {
        val rows = visible()
        return Page(rows.drop(offset).take(limit), rows.size.toLong(), offset, limit)
    }

    override fun listByAuthorId(authorId: Int): List<Note> {
        return visible().filter { it.authorId == authorId }
    }

    override fun insert(entity: Note): Note {
        rows[keyOf(entity)] = entity
        return entity
    }

    override fun update(entity: Note): Note {
        rows[keyOf(entity)] = entity
        return entity
    }

    override fun delete(entity: Note): Unit {
        rows.remove(keyOf(entity))
    }
}

