package app.repositories

import app.Db
import app.Documents
import app.common.Page
import app.entities.Note
import java.util.Collections
import java.util.WeakHashMap
import org.bson.Document

/** Keeps notes rows in the database, through the MongoDB driver. Every write is stored at once. */
class MongoNoteRepository(private val db: Db) : NoteRepository {
    private val collection = "notes"

    /** The fields a change may write */
    private val fields = listOf("text", "authorId")

    override fun findById(id: Int): Note? {
        return db.find(collection, Document("_id", id), limit = 1).firstOrNull()?.let { loaded(it) }
    }

    override fun list(offset: Int, limit: Int): Page<Note> {
        val items = if (limit > 0) db.find(collection, Document(), sort = Document("_id", 1), skip = offset, limit = limit).map { loaded(it) } else emptyList()
        return Page(items, db.count(collection, Document()), offset, limit)
    }

    override fun listByAuthorId(authorId: Int): List<Note> {
        return db.find(collection, Document("authorId", authorId), sort = Document("_id", 1)).map { loaded(it) }
    }

    override fun insert(entity: Note): Note {
        db.insert("Note", collection, toDocument(entity))
        READ[entity] = Documents.copy(toDocument(entity)) as Document
        return entity
    }

    override fun update(entity: Note): Note {
        val now = toDocument(entity)
        val changes = Documents.changes(READ[entity], now, fields)
        if (changes.isNotEmpty()) {
            db.update("Note", collection, Document("_id", now["_id"]), changes)
        }
        READ[entity] = Documents.copy(now) as Document
        return entity
    }

    override fun delete(entity: Note): Unit {
        db.delete("Note", collection, Document("_id", entity.id!!))
    }

    /** The entity of a document, with the document kept to tell its changes. */
    private fun loaded(document: Document): Note {
        val entity = fromDocument(document)
        READ[entity] = Documents.copy(toDocument(entity)) as Document
        return entity
    }

    /** The document of a Note: what is null is left out. */
    private fun toDocument(value: Note): Document {
        val document = Document()
        value.id?.let { document["_id"] = it }
        value.text?.let { document["text"] = it }
        value.authorId?.let { document["authorId"] = it }
        return document
    }

    private fun fromDocument(document: Document): Note =
        Note(
            id = (document["_id"] as Number?)?.toInt(),
            text = document["text"] as String?,
            authorId = (document["authorId"] as Number?)?.toInt(),
        )

    private companion object {
        /** The document each entity was read from: a change writes only the fields that differ */
        val READ: MutableMap<Note, Document> = Collections.synchronizedMap(WeakHashMap())
    }
}

