class MongoUserRepository(private val db: Db) : UserRepository {
    private val collection = "users"

    /** The fields a change may write */
    private val fields = listOf("email")

    override fun findById(id: Int): User? {
        return db.find(collection, Document("_id", id), limit = 1).firstOrNull()?.let { loaded(it) }
    }

    override fun list(offset: Int, limit: Int): Page<User> {
        val items = if (limit > 0) db.find(collection, Document(), sort = Document("_id", 1), skip = offset, limit = limit).map { loaded(it) } else emptyList()
        return Page(items, db.count(collection, Document()), offset, limit)
    }

    override fun findByEmail(email: String): User? {
        return db.find(collection, Document("email", email), limit = 1).firstOrNull()?.let { loaded(it) }
    }

    override fun insert(entity: User): User {
        db.insert("User", collection, toDocument(entity))
        READ[entity] = Documents.copy(toDocument(entity)) as Document
        return entity
    }

    override fun update(entity: User): User {
        val now = toDocument(entity)
        val changes = Documents.changes(READ[entity], now, fields)
        if (changes.isNotEmpty()) {
            db.update("User", collection, Document("_id", now["_id"]), changes)
        }
        READ[entity] = Documents.copy(now) as Document
        return entity
    }

    override fun delete(entity: User): Unit {
        db.delete("User", collection, Document("_id", entity.id!!))
    }

    /** The entity of a document, with the document kept to tell its changes. */
    private fun loaded(document: Document): User {
        val entity = fromDocument(document)
        READ[entity] = Documents.copy(toDocument(entity)) as Document
        return entity
    }

    /** The document of a User: what is null is left out. */
    private fun toDocument(value: User): Document {
        val document = Document()
        value.id?.let { document["_id"] = it }
        value.email?.let { document["email"] = it }
        return document
    }

    private fun fromDocument(document: Document): User =
        User(
            id = (document["_id"] as Number?)?.toInt(),
            email = document["email"] as String?,
        )

    private companion object {
        /** The document each entity was read from: a change writes only the fields that differ */
        val READ: MutableMap<User, Document> = Collections.synchronizedMap(WeakHashMap())
    }
}

