package app.services

import app.UnitOfWork
import app.common.Page
import app.dtos.NoteCreate
import app.dtos.NoteRead
import app.dtos.NoteUpdate
import app.entities.Note
import app.errors.FieldError
import app.errors.NotFoundException
import app.errors.ValidationFailedException

/** Operations on notes. Repositories commit every write. */
class NoteService(private val unitOfWork: UnitOfWork) {
    /** Stores a new Note after checking it. */
    fun createNote(data: NoteCreate): NoteRead {
        val values = mapOf(
            "id" to data.id,
            "text" to data.text,
            "authorId" to data.authorId,
        ).filterValues { it != null }
        return unitOfWork.transaction { uow ->
            checkValues(uow, values, null)
            val entity = Note()
            applyValues(entity, values)
            read(uow.notes.insert(entity))
        }
    }

    /** The Note with this key; NotFoundException when there is none. */
    fun getNote(id: Int): NoteRead = read(find(unitOfWork, id))

    /** A page of notes, by primary key. */
    fun listNotes(offset: Int, limit: Int): Page<NoteRead> = unitOfWork.notes.list(offset, limit).map { read(it) }

    /** Changes the given values of a Note. */
    fun updateNote(id: Int, changes: NoteUpdate): NoteRead {
        val values = given(changes)
        return unitOfWork.transaction { uow ->
            val current = find(uow, id)
            checkValues(uow, values, current)
            applyValues(current, values)
            read(uow.notes.update(current))
        }
    }

    /** Deletes a Note. */
    fun deleteNote(id: Int) {
        unitOfWork.transaction { uow ->
            val current = find(uow, id)
            uow.notes.delete(current)
        }
    }

    /** The notes with this authorId. */
    fun listNotesByAuthorId(authorId: Int): List<NoteRead> = unitOfWork.notes.listByAuthorId(authorId).map { read(it) }

    /** Checks the values against the rules of the "notes" table, and the rows they point to; throws ValidationFailedException with every problem. */
    private fun validate(uow: UnitOfWork, values: Map<String, Any?>, current: Note?) {
        val creating = current == null
        val errors = mutableListOf<FieldError>()
        run {
            val value = values["id"]
            if (value == null) {
                if (creating || "id" in values) errors += FieldError("_id", "is required")
            }
        }
        run {
            val value = values["text"]
            if (value == null) {
                if (creating || "text" in values) errors += FieldError("text", "is required")
            }
        }
        run {
            val value = values["authorId"]
            if (value == null) {
                if (creating || "authorId" in values) errors += FieldError("authorId", "is required")
            }
        }
        run {
            val authorId = if ("authorId" in values) values["authorId"] as Int? else current?.authorId
            if (authorId != null && uow.users.findById(authorId) == null)
                errors += FieldError("authorId", "no User has this key")
        }
        if (errors.isNotEmpty()) throw ValidationFailedException("Note", errors)
    }

    /** Every check before a write: the values, the rows they point to, the unique values. */
    private fun checkValues(uow: UnitOfWork, values: Map<String, Any?>, current: Note?) {
        validate(uow, values, current)
    }

    /** Sets the given values on the entity. */
    private fun applyValues(entity: Note, values: Map<String, Any?>) {
        if ("id" in values) entity.id = values["id"] as Int?
        if ("text" in values) entity.text = values["text"] as String?
        if ("authorId" in values) entity.authorId = values["authorId"] as Int?
    }

    /** The Note with this key; NotFoundException when there is none. */
    private fun find(uow: UnitOfWork, id: Int): Note =
        uow.notes.findById(id) ?: throw NotFoundException("Note", id)

    /** The Note as services return it. */
    private fun read(entity: Note): NoteRead =
        NoteRead(
            id = entity.id!!,
            text = entity.text!!,
            authorId = entity.authorId!!,
        )

    /** The values an update gives, by field. */
    private fun given(changes: NoteUpdate): Map<String, Any?> {
        val values = mutableMapOf<String, Any?>()
        if (changes.text.isPresent) values["text"] = changes.text.value
        if (changes.authorId.isPresent) values["authorId"] = changes.authorId.value
        return values
    }
}

