/** Operations on users. Repositories commit every write. */
class UserService(private val unitOfWork: UnitOfWork) {
    /** Stores a new User after checking it. */
    fun createUser(data: UserCreate): UserRead {
        val values = mapOf(
            "id" to data.id,
            "email" to data.email,
        ).filterValues { it != null }
        return unitOfWork.transaction { uow ->
            checkValues(uow, values, null)
            val entity = User()
            applyValues(entity, values)
            read(uow.users.insert(entity))
        }
    }

    /** The User with this key; NotFoundException when there is none. */
    fun getUser(id: Int): UserRead = read(find(unitOfWork, id))

    /** A page of users, by primary key. */
    fun listUsers(offset: Int, limit: Int): Page<UserRead> = unitOfWork.users.list(offset, limit).map { read(it) }

    /** Changes the given values of a User. */
    fun updateUser(id: Int, changes: UserUpdate): UserRead {
        val values = given(changes)
        return unitOfWork.transaction { uow ->
            val current = find(uow, id)
            checkValues(uow, values, current)
            applyValues(current, values)
            read(uow.users.update(current))
        }
    }

    /** Deletes a User. */
    fun deleteUser(id: Int) {
        unitOfWork.transaction { uow ->
            val current = find(uow, id)
            if (uow.notes.listByAuthorId(current.id!!).isNotEmpty())
                throw ConflictException("User", "rows of notes still point to it", listOf("notes"))
            uow.users.delete(current)
        }
    }

    /** The User with this email, or null. */
    fun findUserByEmail(email: String): UserRead? = unitOfWork.users.findByEmail(email)?.let { read(it) }

    /** Checks the values against the rules of the "users" table, and the rows they point to; throws ValidationFailedException with every problem. */
    private fun validate(uow: UnitOfWork, values: Map<String, Any?>, current: User?) {
        val creating = current == null
        val errors = mutableListOf<FieldError>()
        run {
            val value = values["id"]
            if (value == null) {
                if (creating || "id" in values) errors += FieldError("_id", "is required")
            }
        }
        run {
            val value = values["email"]
            if (value == null) {
                if (creating || "email" in values) errors += FieldError("email", "is required")
            }
        }
        if (errors.isNotEmpty()) throw ValidationFailedException("User", errors)
    }

    /** Values that must be unique are not taken by another row. */
    private fun checkUnique(uow: UnitOfWork, values: Map<String, Any?>, current: User?) {
        run {
            val email = if ("email" in values) values["email"] as String? else current?.email
            if (email != null) {
                val other = uow.users.findByEmail(email)
                if (other != null && (current == null || other.id != current.id))
                    throw ConflictException("User", "email is already taken", listOf("email"))
            }
        }
    }

    /** Every check before a write: the values, the rows they point to, the unique values. */
    private fun checkValues(uow: UnitOfWork, values: Map<String, Any?>, current: User?) {
        validate(uow, values, current)
        checkUnique(uow, values, current)
    }

    /** Sets the given values on the entity. */
    private fun applyValues(entity: User, values: Map<String, Any?>) {
        if ("id" in values) entity.id = values["id"] as Int?
        if ("email" in values) entity.email = values["email"] as String?
    }

    /** The User with this key; NotFoundException when there is none. */
    private fun find(uow: UnitOfWork, id: Int): User =
        uow.users.findById(id) ?: throw NotFoundException("User", id)

    /** The User as services return it. */
    private fun read(entity: User): UserRead =
        UserRead(
            id = entity.id!!,
            email = entity.email!!,
        )

    /** The values an update gives, by field. */
    private fun given(changes: UserUpdate): Map<String, Any?> {
        val values = mutableMapOf<String, Any?>()
        if (changes.email.isPresent) values["email"] = changes.email.value
        return values
    }
}

